      .update(s.waitlistEntries)
      .set({ status: "offered" })
      .where(and(eq(s.waitlistEntries.id, entry.id), eq(s.waitlistEntries.status, "booked")));
    return { ok: false, error: "slot_taken" };
  }

  await db
    .update(s.waitlistEntries)
    .set({ offerToken: null, offerHoldToken: null })
    .where(eq(s.waitlistEntries.id, entry.id));
