p='src/lib/waitlist.integration.test.ts'
t=open(p).read()
t=t.replace('import { acceptOffer, expireOffer, joinWaitlist }','import { acceptOffer, declineOffer, expireOffer, joinWaitlist }')
t+='''
describe("declining an offer", () => {
  async function offerToFirst() {
    const booked = await book();
    await join("+77012222222"); // first
    await join("+77013333333"); // second
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    return (await entries()).find((r) => r.status === "offered")!;
  }

  const free = () =>
    getAvailability({
      businessId: f.business.id,
      timeZone: f.business.timezone,
      staffId: f.master.id,
      serviceId: f.service.id,
      dateISO: date,
    });

  it("kills the link and offers the slot to the next client once, even on a double tap", async () => {
    const first = await offerToFirst();
    const results = await Promise.all([
      declineOffer(first.offerToken!),
      declineOffer(first.offerToken!),
      declineOffer(first.offerToken!),
    ]);
    expect(results.every((r) => r.ok)).toBe(true);
    expect((await acceptOffer(first.offerToken!)).ok).toBe(false);

    await drainOnce();
    await drainOnce();

    const rows = await entries();
    expect(rows.find((r) => r.id === first.id)!.status).toBe("declined");
    const offered = rows.filter((r) => r.status === "offered");
    expect(offered).toHaveLength(1);
    expect(offered[0].id).not.toBe(first.id);
    const offerSms = (await messages()).filter((m) => m.subject.includes("a slot has opened up"));
    expect(offerSms.filter((m) => m.recipient === "+77013333333")).toHaveLength(1);
  });

  it("puts the slot back on the public page at once when nobody else waits", async () => {
    const booked = await book();
    await join("+77012222222");
    await cancel((booked as { bookingId: string }).bookingId);
    await drainOnce();
    const only = (await entries()).find((r) => r.status === "offered")!;

    await declineOffer(only.offerToken!);
    expect((await free()).map((sl) => sl.startMs)).toContain(slotAt().startMs);

    await drainOnce();
    expect((await entries())[0].status).toBe("declined");
  });

  it("does nothing once the offer has been claimed", async () => {
    const first = await offerToFirst();
    expect((await acceptOffer(first.offerToken!)).ok).toBe(true);

    expect((await declineOffer(first.offerToken!)).ok).toBe(false);
    await drainOnce();

    const rows = await entries();
    expect(rows.find((r) => r.id === first.id)!.status).toBe("booked");
    expect(rows.filter((r) => r.status === "offered")).toHaveLength(0);
    expect(await db.select().from(s.bookings).where(eq(s.bookings.status, "confirmed")))
      .toHaveLength(1);
  });
});
'''
